"""设备维修工单协同平台 — REST API 服务实现（Flask + SQLite）。

契约：deliverables/docs/interface.md（IC-MAINT-1.0，frozen）。数据来源：synthetic_fixture（LOCAL ONLY）。

运行：
    python app.py --db <sqlite 路径> --port <端口>
    环境变量 APP_DB_PATH / APP_PORT 分别覆盖库路径与端口（APP_DB_PATH 优先于 --db）。
本模块同时负责：Schema、幂等种子初始化（启动时调用 db.seed）、统一错误响应、
服务端会话身份与角色权限校验、工单状态机迁移校验、事务化备件领用、幂等键防重、统计查询。
"""
import argparse
import hashlib
import json
import os
import sqlite3
import sys
import uuid
from datetime import datetime, timedelta
from functools import wraps

from flask import Flask, Response, g, jsonify, redirect, request, send_from_directory

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import db as dbmod  # noqa: E402

BACKEND_DIR = os.path.dirname(os.path.abspath(__file__))
FRONTEND_DIR = os.path.abspath(os.path.join(BACKEND_DIR, "..", "frontend"))
SCHEMA_FILE = os.path.join(BACKEND_DIR, "schema.sql")

ROLES = ("employee", "engineer", "admin")
WO_STATUSES = ("open", "assigned", "in_progress", "completed", "closed")
PRIORITIES = ("P1", "P2", "P3")
CRITICALITIES = ("高", "中", "低")
ASSET_STATUSES = ("运行中", "告警", "停机", "维修中")
SLA_HOURS = {"P1": 4, "P2": 24, "P3": 72}
SESSION_TTL_SECONDS = int(os.environ.get("SESSION_TTL_SECONDS", "28800"))
IDEMPOTENT_SCOPES = {"login", "create_work_order", "create_asset", "create_part",
                     "assign", "start", "complete", "close", "issue_part"}
IDENTITY_FIELDS = ("role", "user_id", "actor_id")
TS_FMT = "%Y-%m-%dT%H:%M:%S"
APP_STARTED_AT = datetime.now().strftime(TS_FMT)


# ------------------------------------------------------------------ 时间/工具
def now_str():
    return datetime.now().strftime(TS_FMT)


def parse_ts(value):
    if not value:
        return None
    return datetime.strptime(str(value)[:19], TS_FMT)


def iso(value):
    if value is None:
        return None
    return str(value)[:19]


# ------------------------------------------------------------------ 统一错误
class ApiError(Exception):
    def __init__(self, code, message, status, details=None):
        super().__init__(message)
        self.code = code
        self.message = message
        self.status = status
        self.details = details or {}

    def envelope(self):
        return {"ok": False,
                "error": {"code": self.code, "message": self.message,
                          "http_status": self.status, "details": self.details}}


def err_validation(field, reason=None, extra=None):
    details = {"field": field}
    if reason:
        details["reason"] = reason
    if extra:
        details.update(extra)
    return ApiError("VALIDATION_ERROR", "请求字段校验失败：%s" % field, 400, details)


def err_forbidden(message, **details):
    return ApiError("FORBIDDEN", message, 403, details)


def err_not_found(resource, rid):
    return ApiError("NOT_FOUND", "%s %s 不存在" % (resource, rid), 404,
                    {"resource": resource, "id": rid})


def err_transition(wo_id, current, operation):
    return ApiError("INVALID_TRANSITION", "工单 %s 当前状态 %s 不能执行 %s" % (wo_id, current, operation),
                    409, {"work_order_id": wo_id, "current_status": current, "operation": operation})


def err_stock(part_id, requested, on_hand):
    return ApiError("INSUFFICIENT_STOCK", "备件 %s 库存不足" % part_id, 409,
                    {"part_id": part_id, "requested": requested, "on_hand": on_hand})


def err_duplicate(resource, rid):
    return ApiError("DUPLICATE_ID", "%s %s 已存在" % (resource, rid), 409, {"resource": resource, "id": rid})


# ------------------------------------------------------------------ 数据库连接
def _concurrent_ddl_error(exc):
    """并发首请求窗口内的无害 DDL 竞争（表已存在 / 库忙 / 列已加）。"""
    text = str(exc).lower()
    return ("already exists" in text or "locked" in text or "busy" in text
            or "duplicate column" in text)


def _heal_retry(conn):
    """建表失败的有界重试；极短窗口内仍失败则如实抛出原异常，不伪造成功。"""
    import time as _time
    delay, last = 0.0, None
    for _ in range(6):
        try:
            dbmod.init_schema(conn)
            dbmod.seed(conn)
            return
        except sqlite3.Error as exc:
            last = exc
            if not _concurrent_ddl_error(exc):
                raise
            if delay:
                _time.sleep(delay)
            delay = 0.04 if not delay else min(delay * 2, 0.2)
    raise last


def _complete_schema(conn):
    """业务 schema 完整性哨兵：契约元表之外，业务侧关键表必须同时存在。"""
    row = conn.execute(
        "SELECT COUNT(*) AS n FROM sqlite_master WHERE type='table' AND name IN (?, ?)",
        (dbmod.BUSINESS_SENTINEL_TABLE, "users")).fetchone()
    return row["n"] == 2


def schema_absent_error(exc):
    """未初始化库的信号：缺表 / 缺列（即「需要建表自愈」）。"""
    text = str(exc).lower()
    return "no such table" in text or "has no column named" in text


def _self_heal(conn):
    """幂等自愈：任何请求进入业务逻辑前，契约元表 + 业务 schema 必已就绪。

    语义边界：
      - 每次请求仅一次廉价 sqlite_master 探测，表齐备即不再产生任何写操作，
        不 DELETE / DROP / 不清空既有数据（库被替换为空文件时再次自愈）；
      - `ensure_meta_tables` / `init_schema` / `seed` 内部均为 IF NOT EXISTS /
        INSERT OR IGNORE，重复调用无副作用；
      - 失败路径不吞异常：确实无表可建时抛出真实错误（由统一错误信封回传 500）。
    """
    path = g.get("path")
    dbmod.ensure_meta_tables(conn)
    if _complete_schema(conn):
        g.seed_checked = True
        return
    if os.environ.get("ASTRALNEXUS_DIAG"):
        names = [r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type='table'")]
        print("[diag] self_heal path=%s tables_before=%s" % (path, names))
    try:
        dbmod.seed(conn)
    except sqlite3.Error as exc:
        if schema_absent_error(exc) or _concurrent_ddl_error(exc):
            _heal_retry(conn)
        else:
            raise
    if not _complete_schema(conn):
        raise RuntimeError("database self-heal incomplete: schema still missing at %s" % path)
    if os.environ.get("ASTRALNEXUS_DIAG"):
        print("[diag] self_heal path=%s healed=True" % path)
    g.seed_checked = True


def open_conn():
    """建立请求级连接；冷启动自愈：目录缺失则创建，元表 + 业务表缺失则建表并幂等播种。

    自愈先于任何业务查询：指向全新未初始化 SQLite 路径的服务，首个请求
    （含首个 POST /api/login）进入业务逻辑前即完成建表，因此返回契约定义的
    200 / 4xx 统一错误信封，而不是 `no such table` 导致的 500 INTERNAL_ERROR。
    幂等：CREATE TABLE IF NOT EXISTS / INSERT OR IGNORE / 单次 schema 探测。
    """
    path = os.path.abspath(str(g.db_path))
    directory = os.path.dirname(path)
    if directory:
        os.makedirs(directory, exist_ok=True)
    conn = dbmod.connect(path)
    g.conn = conn
    g.path = path
    _self_heal(conn)
    return conn


def close_conn(exc=None):
    conn = g.pop("conn", None)
    if conn is not None:
        try:
            conn.close()
        except sqlite3.Error:
            pass
    return exc


def get_conn():
    """请求级连接；首次调用即完成幂等自愈，已有连接直接复用（同一请求内不重连）。"""
    existing = g.get("conn")
    if existing is not None:
        return existing
    if g.get("conn_failed"):
        # 本请求内自愈已确认失败：不再反复重试，如实抛出原异常（不伪造成功）。
        raise RuntimeError("database self-heal failed for %s" % g.get("path"))
    try:
        return open_conn()
    except sqlite3.Error as exc:
        g.conn_failed = True
        raise exc


def ensure_ready():
    """首次请求前完成 schema + 幂等播种（复用测试/CLI 已经初始化好的库）。

    实际自愈逻辑集中在 open_conn()：目录缺失则创建、业务表缺失则建表 + 幂等播种；
    已就绪的库直接复用，重复调用无副作用，不清空既有数据。
    """
    if g.get("seed_checked"):
        return
    get_conn()


# ------------------------------------------------------------------ 序列化
def user_dict(row):
    return {"user_id": row["user_id"], "username": row["username"], "name": row["name"],
            "role": row["role"], "workshop": row["workshop"]}


def asset_dict(row, open_count=None):
    data = {"asset_id": row["asset_id"], "workshop": row["workshop"], "asset_name": row["asset_name"],
            "criticality": row["criticality"], "last_inspection": row["last_inspection"],
            "status": row["status"]}
    if open_count is not None:
        data["open_work_order_count"] = open_count
    elif "open_work_order_count" in row.keys():
        data["open_work_order_count"] = row["open_work_order_count"]
    return data


def part_dict(row):
    on_hand = row["on_hand"]
    reorder = row["reorder_point"]
    return {"part_id": row["part_id"], "name": row["name"], "on_hand": on_hand,
            "reorder_point": reorder, "unit_cost_cny": row["unit_cost_cny"],
            "shortage": bool(on_hand < reorder),
            "shortage_qty": max(reorder - on_hand, 0)}


def part_issue_dict(row):
    return {"issue_id": row["issue_id"], "work_order_id": row["work_order_id"], "part_id": row["part_id"],
            "quantity": row["quantity"], "issued_to": row["issued_to"],
            "issued_at": iso(row["issued_at"]), "unit_cost_cny": row["unit_cost_cny"]}


def work_order_dict(conn, row, include_issues=False):
    data = {"work_order_id": row["work_order_id"], "asset_id": row["asset_id"],
            "fault_desc": row["fault_desc"], "priority": row["priority"], "status": row["status"],
            "reported_at": iso(row["reported_at"]), "reporter_id": row["reporter_id"],
            "assigned_to": row["assigned_to"], "required_part": row["required_part"],
            "created_at": iso(row["created_at"]), "assigned_at": iso(row["assigned_at"]),
            "started_at": iso(row["started_at"]), "completed_at": iso(row["completed_at"]),
            "closed_at": iso(row["closed_at"]), "resolution_note": row["resolution_note"]}
    asset = conn.execute(
        "SELECT asset_id, asset_name, workshop FROM assets WHERE asset_id=?", (row["asset_id"],)).fetchone()
    if asset:
        data["asset"] = {"asset_id": asset["asset_id"], "asset_name": asset["asset_name"],
                         "workshop": asset["workshop"]}
    if include_issues:
        rows = conn.execute(
            "SELECT * FROM part_issues WHERE work_order_id=? ORDER BY issue_id", (row["work_order_id"],)).fetchall()
        data["part_issues"] = [part_issue_dict(r) for r in rows]
    return data


# ------------------------------------------------------------------ 响应封装
def ok(data, meta=None, status=200):
    payload = {"ok": True, "data": data, "meta": meta or {}}
    return jsonify(payload), status


def parse_json_body(required=True):
    raw = request.get_data(as_text=True)
    if not raw or not raw.strip():
        if required:
            raise ApiError("VALIDATION_ERROR", "请求体不能为空", 400, {"field": "body", "reason": "empty_body"})
        return {}
    try:
        body = json.loads(raw)
    except (ValueError, TypeError):
        raise ApiError("VALIDATION_ERROR", "请求体必须是合法 JSON 对象", 400,
                       {"field": "body", "reason": "invalid_json"})
    if body is None:
        body = {}
    if not isinstance(body, dict):
        raise ApiError("VALIDATION_ERROR", "请求体必须是 JSON 对象", 400,
                       {"field": "body", "reason": "not_an_object"})
    return body


def reject_identity_fields(conn, body, allow=()):
    """请求体出现身份类字段 → 400 + 审计身份伪造尝试。"""
    for field in list(IDENTITY_FIELDS) + ["reporter_id", "issued_to"]:
        if field in body and field not in allow:
            write_audit(conn, None, "identity_spoof_attempt", detail=json.dumps({"field": field}, ensure_ascii=False))
            raise ApiError("VALIDATION_ERROR", "身份字段 %s 只能来自服务端会话" % field, 400,
                           {"field": field, "reason": "identity_from_session_only"})


def write_audit(conn, actor_id, action, work_order_id=None, before=None, after=None,
                idempotency_key=None, detail=None):
    conn.execute(
        "INSERT INTO audit_log (actor_id, action, work_order_id, before_status, after_status,"
        " idempotency_key, detail, created_at) VALUES (?,?,?,?,?,?,?,?)",
        (actor_id, action, work_order_id, before, after, idempotency_key, detail, now_str()))


# ------------------------------------------------------------------ 会话
def current_session(conn):
    token = request.cookies.get("session_token")
    if not token:
        token = request.headers.get("X-Session-Token")
    if not token:
        raise ApiError("UNAUTHENTICATED", "缺少有效会话", 401, {"reason": "missing_session"})
    row = conn.execute("SELECT * FROM sessions WHERE token=?", (token,)).fetchone()
    if not row:
        raise ApiError("UNAUTHENTICATED", "会话未知或已过期", 401, {"reason": "unknown_session"})
    if parse_ts(row["expires_at"]) < datetime.now():
        raise ApiError("UNAUTHENTICATED", "会话已过期", 401, {"reason": "expired_session"})
    user = conn.execute("SELECT * FROM users WHERE user_id=?", (row["user_id"],)).fetchone()
    if not user:
        raise ApiError("UNAUTHENTICATED", "会话用户不存在", 401, {"reason": "unknown_user"})
    return {"token": row["token"], "expires_at": row["expires_at"], "user": user}


def login_required(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        conn = get_conn()
        ensure_ready()
        # 查询串中的身份类参数一律忽略并记审计，绝不用它替代会话身份
        for field in IDENTITY_FIELDS:
            if field in request.args:
                write_audit(conn, None, "identity_param_ignored",
                            detail=json.dumps({"field": field, "path": request.path}, ensure_ascii=False))
        g.session = current_session(conn)
        return fn(*args, **kwargs)
    return wrapper


def require_roles(*roles):
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            session = g.session
            if session["user"]["role"] not in roles:
                raise err_forbidden("角色 %s 无权执行该操作" % session["user"]["role"],
                                    required_roles=list(roles), actual_role=session["user"]["role"])
            return fn(*args, **kwargs)
        return wrapper
    return decorator


# ------------------------------------------------------------------ 幂等键
def request_fingerprint(scope, body):
    raw = json.dumps({"scope": scope, "method": request.method, "path": request.path,
                      "query": sorted(request.args.items(multi=True)), "body": body},
                     sort_keys=True, ensure_ascii=False)
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def require_idempotency_key():
    key = request.headers.get("X-Idempotency-Key")
    if not key or not key.strip():
        raise ApiError("VALIDATION_ERROR", "写操作必须携带幂等键请求头", 400,
                       {"field": "X-Idempotency-Key", "reason": "missing_idempotency_key"})
    key = key.strip()
    if len(key) > 128 or not all(c.isalnum() or c in "._:-" for c in key):
        raise ApiError("VALIDATION_ERROR", "幂等键格式非法（允许 [A-Za-z0-9._:-]，长度 1-128）", 400,
                       {"field": "X-Idempotency-Key", "reason": "invalid_idempotency_key"})
    return key


def idempotent(scope, resource_id=None, required=True, replay_authz=None):
    """幂等键防重装饰器：同键同内容回放首次响应；同键异内容 → 409 且无副作用。

    被包装函数返回 (response_body_dict, status, resource_id)；业务 4xx 失败不占用幂等键。
    required=False 用于 §6 标注「幂等键=否」的写操作（仅 login）：不强制携带，但一旦携带
    仍按 scope=login 记录与校验，缺省时由服务端生成一次性键，避免窃取客户端幂等语义。
    """
    assert scope in IDEMPOTENT_SCOPES, "非法幂等作用域：%s" % scope

    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            raw_key = request.headers.get("X-Idempotency-Key")
            if required or (raw_key and raw_key.strip()):
                key = require_idempotency_key()
            else:
                key = "auto:" + uuid.uuid4().hex
            conn = get_conn()
            # 冷启动自愈：契约元表（幂等键/会话/审计）先于任何业务查询建立，
            # 修复「幂等键查询发生在业务表建立之前」导致的未初始化库 500。
            dbmod.ensure_meta_tables(conn)
            g.write_conn = conn
            body = parse_json_body(required=False)
            fingerprint = request_fingerprint(scope, body)
            g.idempotency_key = key
            g.idempotency_body = body
            row = conn.execute(
                "SELECT * FROM idempotency_keys WHERE scope=? AND idempotency_key=?", (scope, key)).fetchone()
            if row:
                # 裁定 §12.1（§4.4 步骤3先于步骤4与回放）：幂等键重放必须先过与首次请求
                # 同源的权限校验，否则未授权角色可用他人已用过的键绕过 403 判定。
                if replay_authz is not None:
                    replay_authz(*args, **kwargs)
                if row["request_hash"] != fingerprint:
                    raise ApiError("IDEMPOTENCY_CONFLICT", "幂等键已被不同请求内容占用", 409,
                                   {"idempotency_key": key, "scope": scope})
                stored = json.loads(row["response_body"])
                if isinstance(stored, dict) and stored.get("ok") is True:
                    meta = dict(stored.get("meta") or {})
                    meta["idempotency_key"] = key
                    meta["idempotent_replay"] = True
                    stored = {"ok": True, "data": stored.get("data"), "meta": meta}
                return attach_session_cookie(jsonify(stored), stored), row["response_status"]
            status, payload = normalize_result(fn(*args, **kwargs))
            return _store_and_respond(conn, scope, key, fingerprint, status, payload)
        return wrapper
    return decorator


def _store_and_respond(conn, scope, key, fingerprint, status, payload, resource_id=None):
    if status >= 400:
        return jsonify(payload), status
    meta = dict(payload.get("meta") or {})
    meta["idempotency_key"] = key
    meta["idempotent_replay"] = False
    payload = {"ok": True, "data": payload.get("data"), "meta": meta}
    if resource_id is None:
        data = payload.get("data")
        if isinstance(data, dict):
            resource_id = data.get("work_order_id") or data.get("asset_id") or data.get("part_id")
            if resource_id is None and data.get("issue_id") is not None:
                resource_id = "%s#%s" % (data.get("work_order_id"), data.get("issue_id"))
    conn.execute(
        "INSERT OR REPLACE INTO idempotency_keys (idempotency_key, scope, request_hash, response_status,"
        " response_body, resource_id, created_at) VALUES (?,?,?,?,?,?,?)",
        (key, scope, fingerprint, status, json.dumps(payload, ensure_ascii=False), resource_id, now_str()))
    return attach_session_cookie(jsonify(payload), payload), status


# ------------------------------------------------------------------ 结果规范化
_PENDING_COOKIE = "pending_session_token"


def normalize_result(result):
    """把视图返回值统一成 (status, payload_dict)，并在请求上下文中暂存待下发会话 cookie。"""
    if isinstance(result, tuple):
        if len(result) == 2:
            return int(result[0]), result[1]
        if len(result) == 3:
            status, payload, token = result
            if token:
                g.setdefault(_PENDING_COOKIE, token)
            return int(status), payload
        raise ApiError("INTERNAL_ERROR", "视图返回值元组长度非法", 500, {"length": len(result)})
    if hasattr(result, "get_json"):
        raise ApiError("INTERNAL_ERROR", "视图必须返回 (status, payload) 或 (status, payload, token)", 500, {})
    return int(result[0]), result[1]


def attach_session_cookie(response, payload):
    """登录响应（含幂等回放）重新下发 HttpOnly 会话 cookie。"""
    token = g.get(_PENDING_COOKIE)
    if not token and isinstance(payload, dict):
        data = payload.get("data")
        if isinstance(data, dict):
            token = data.get("session_token")
    if token:
        response.set_cookie("session_token", token, httponly=True, samesite="Lax",
                            max_age=SESSION_TTL_SECONDS)
    return response


# ------------------------------------------------------------------ 字段校验
def pick_str(body, field, required=False, max_len=None, min_len=None, allow_none=False):
    if field not in body or body[field] is None:
        if allow_none:
            return None
        if required:
            raise err_validation(field, "required")
        return None
    value = body[field]
    if not isinstance(value, str):
        raise err_validation(field, "must_be_string")
    value = value.strip()
    if required and not value:
        raise err_validation(field, "required")
    if min_len is not None and len(value) < min_len:
        raise err_validation(field, "too_short", {"min_length": min_len})
    if max_len is not None and len(value) > max_len:
        raise err_validation(field, "too_long", {"max_length": max_len})
    return value or None


def pick_enum(body, field, allowed, required=True):
    value = pick_str(body, field, required=required)
    if value is None and not required:
        return None
    if value not in allowed:
        raise err_validation(field, "invalid_enum", {"allowed": list(allowed)})
    return value


def pick_int(body, field, required=True, minimum=None, maximum=None):
    if field not in body or body[field] is None:
        if required:
            raise err_validation(field, "required")
        return None
    value = body[field]
    if isinstance(value, bool) or not isinstance(value, (int, float, str)):
        raise err_validation(field, "must_be_integer")
    try:
        ivalue = int(str(value).strip())
    except (TypeError, ValueError):
        raise err_validation(field, "must_be_integer")
    if isinstance(value, float) and value != ivalue:
        raise err_validation(field, "must_be_integer")
    if minimum is not None and ivalue < minimum:
        raise err_validation(field, "out_of_range", {"min": minimum})
    if maximum is not None and ivalue > maximum:
        raise err_validation(field, "out_of_range", {"max": maximum})
    return ivalue


def pick_number(body, field, required=True, minimum=None):
    if field not in body or body[field] is None:
        if required:
            raise err_validation(field, "required")
        return None
    value = body[field]
    if isinstance(value, bool) or not isinstance(value, (int, float, str)):
        raise err_validation(field, "must_be_number")
    try:
        fvalue = float(str(value).strip())
    except (TypeError, ValueError):
        raise err_validation(field, "must_be_number")
    if minimum is not None and fvalue < minimum:
        raise err_validation(field, "out_of_range", {"min": minimum})
    return fvalue


def pick_date(body, field, required=True):
    value = pick_str(body, field, required=required)
    if value is None:
        return None
    try:
        datetime.strptime(value, "%Y-%m-%d")
    except ValueError:
        raise err_validation(field, "invalid_date", {"format": "YYYY-MM-DD"})
    return value


def reject_unknown(body, allowed):
    unknown = sorted(set(body) - set(allowed))
    if unknown:
        raise err_validation(unknown[0], "unknown_field", {"allowed": sorted(allowed)})


