    def api_login():
        # 冷启动自愈：首个请求为登录时，业务库由幂等装饰器已建立元表（写连接），
        # 此处直接复用，使未初始化库上的首次 POST /api/login 返回契约 200。
        conn = g.get("write_conn") or get_conn()
        g.conn = conn
        body = g.idempotency_body
