        user = conn.execute("SELECT * FROM users WHERE username=?", (username,)).fetchone()
        if not user or user["password"] != password:
            write_audit(conn, None, "login_failed", detail=json.dumps({"username": username}, ensure_ascii=False))
            return 401, {"ok": False, "error": {"code": "UNAUTHENTICATED", "message": "用户名或密码错误",
