                     (token, user["user_id"], issued, expires))
        write_audit(conn, user["user_id"], "login")
        payload = {"session_token": token, "expires_at": expires, "user": user_dict(user)}
        # 身份只由服务端会话表定义；视图统一返回 (status, body_dict, token)
