def _load_session_by_token(conn, token):
    if not token:
        return None
    return conn.execute("SELECT * FROM sessions WHERE token=?", (token,)).fetchone()


def visible_work_order(conn, row, role, user_id, action="view"):
    """可见性校验：员工仅本人报修、工程师仅被分配、管理员全部。"""
    if role == "admin":
        return
    if role == "employee":
        if row["reporter_id"] != user_id:
            raise ApiError("FORBIDDEN", "无权查看该工单", 403,
                           {"work_order_id": row["work_order_id"], "reporter_id": row["reporter_id"],
                            "actual_role": role})
        return
    if role == "engineer":
        if row["assigned_to"] != user_id:
            raise ApiError("FORBIDDEN", "无权操作未被分配给自己工单 %s" % row["work_order_id"], 403,
                           {"work_order_id": row["work_order_id"], "assigned_to": row["assigned_to"],
                            "actual_role": role})
        return
    raise err_forbidden("角色 %s 无权访问工单" % role, actual_role=role)


def transition_work_order(conn, wo_id, operation):
    """T1–T4 状态机迁移：越权 403 / 非法迁移 409 / 状态已达成 200 幂等。"""
    row = fetch_work_order(conn, wo_id)
    if not row:
        raise err_not_found("work_order", wo_id)
    session = g.session
    actor_id = session["user"]["user_id"]
    actor_role = session["user"]["role"]
    key = getattr(g, "idempotency_key", None)
    body = getattr(g, "idempotency_body", {}) or {}

    visible_work_order(conn, row, actor_role, actor_id, action=operation)
    current = row["status"]
    meta = {"source": row["source"]}
    if operation in ("start", "complete", "close") and actor_role not in ("engineer", "admin"):
        raise err_forbidden("角色 %s 无权执行 %s" % (actor_role, operation),
                            required_roles=["engineer", "admin"], actual_role=actor_role)
    if operation == "assign" and actor_role != "admin":
        raise err_forbidden("角色 %s 无权执行 assign" % actor_role,
                            required_roles=["admin"], actual_role=actor_role)
    if operation == "close" and actor_role != "admin":
        # 裁定 §12.2（§3 T4）：completed→closed 允许角色仅 admin；engineer 即便被分配也 403。
        raise err_forbidden("角色 %s 无权执行 close" % actor_role,
                            required_roles=["admin"], actual_role=actor_role)

    if operation == "assign":
        assigned_to = pick_str(body, "assigned_to", required=True, max_len=32)
        target = conn.execute("SELECT * FROM users WHERE user_id=?", (assigned_to,)).fetchone()
        if not target or target["role"] != "engineer":
            raise err_validation("assigned_to", "must_be_engineer", {"allowed_roles": ["engineer"]})
        if current == "open":
            conn.execute("UPDATE work_orders SET status='assigned', assigned_to=?, assigned_at=? WHERE work_order_id=?",
                         (assigned_to, now_str(), wo_id))
            write_audit(conn, actor_id, "work_order.assign", wo_id, current, "assigned", key)
        elif current != "assigned" or row["assigned_to"] != assigned_to:
            raise err_transition(wo_id, current, operation)
    else:
        target_status = {"start": "in_progress", "complete": "completed", "close": "closed"}[operation]
        expected = {"start": "assigned", "complete": "in_progress", "close": "completed"}[operation]
        if current != expected:
            raise err_transition(wo_id, current, operation)
        if operation == "start":
            conn.execute("UPDATE work_orders SET status='in_progress', started_at=? WHERE work_order_id=?",
                         (now_str(), wo_id))
        elif operation == "complete":
            note = pick_str(body, "resolution_note", required=True, min_len=1, max_len=500)
            required_part = row["required_part"]
            if required_part:
                issued_qty = conn.execute(
                    "SELECT COALESCE(SUM(quantity),0) AS qty FROM part_issues"
                    " WHERE work_order_id=? AND part_id=?", (wo_id, required_part)).fetchone()["qty"]
                if not issued_qty:
                    # 裁定 §12.3（§3 T3 前置条件）：存在必有备件时必须先领用成功方可 complete。
                    raise ApiError("INVALID_TRANSITION",
                                   "工单 %s 必有备件 %s 尚未领用，不能 complete" % (wo_id, required_part),
                                   409, {"work_order_id": wo_id, "current_status": current,
                                         "operation": operation, "reason": "required_part_not_issued",
                                         "required_part": required_part})
            conn.execute("UPDATE work_orders SET status='completed', completed_at=?, resolution_note=?"
                         " WHERE work_order_id=?", (now_str(), note, wo_id))
        else:
            pick_str(body, "note", required=False, max_len=500)
            conn.execute("UPDATE work_orders SET status='closed', closed_at=? WHERE work_order_id=?",
                         (now_str(), wo_id))
        write_audit(conn, actor_id, "work_order.%s" % operation, wo_id, current, target_status, key)

    return 200, {"data": work_order_dict(conn, fetch_work_order(conn, wo_id)), "meta": meta}


def _transition_replay_guard(operation):
    """幂等键重放前的权限校验：复刻 transition_work_order 的同一判定顺序（存在性→可见性→角色），
    仅用于「首次请求已占键、后续请求走回放分支」时补上步骤 3，不改变首次请求的任何语义。"""
    def guard(wo_id):
        conn = get_conn()
        row = fetch_work_order(conn, wo_id)
        if not row:
            raise err_not_found("work_order", wo_id)
        session = g.session
        actor_id = session["user"]["user_id"]
        actor_role = session["user"]["role"]
        visible_work_order(conn, row, actor_role, actor_id, action=operation)
        if operation in ("start", "complete", "close") and actor_role not in ("engineer", "admin"):
            raise err_forbidden("角色 %s 无权执行 %s" % (actor_role, operation),
                                required_roles=["engineer", "admin"], actual_role=actor_role)
        if operation in ("assign", "close") and actor_role != "admin":
            raise err_forbidden("角色 %s 无权执行 %s" % (actor_role, operation),
                                required_roles=["admin"], actual_role=actor_role)
    return guard


def _part_issue_replay_guard(wo_id):
    """领用路由（scope=issue_part）幂等重放前的权限校验，与首次请求同源。"""
    conn = get_conn()
    row = fetch_work_order(conn, wo_id)
    if not row:
        raise err_not_found("work_order", wo_id)
    actor_id = g.session["user"]["user_id"]
    actor_role = g.session["user"]["role"]
    visible_work_order(conn, row, actor_role, actor_id, action="issue")
    if actor_role not in ("engineer", "admin"):
        raise err_forbidden("角色 %s 无权领用备件" % actor_role,
                            required_roles=["engineer", "admin"], actual_role=actor_role)


def register_work_order_routes(app):
