        if status:
            if status not in WO_STATUSES:
                raise err_validation("status", "invalid_enum", {"allowed": list(WO_STATUSES)})
            clauses.append("wo.status = ?")
            params.append(status)
        priority = request.args.get("priority")
        if priority:
            if priority not in PRIORITIES:
                raise err_validation("priority", "invalid_enum", {"allowed": list(PRIORITIES)})
            clauses.append("wo.priority = ?")
            params.append(priority)
        workshop = request.args.get("workshop")
        if workshop:
            clauses.append("a.workshop = ?")
            params.append(workshop)
        asset_id = request.args.get("asset_id")
        if asset_id:
            clauses.append("wo.asset_id = ?")
            params.append(asset_id)
        assigned_to = request.args.get("assigned_to")
        if assigned_to:
            if role == "engineer" and assigned_to != user_id:
                raise err_forbidden("工程师只能按自身过滤工单", actual_role=role)
            clauses.append("wo.assigned_to = ?")
            params.append(assigned_to)
        sla_risk = request.args.get("sla_risk")
        if sla_risk and sla_risk.lower() == "true":
            if role != "admin":
                raise err_forbidden("SLA 风险筛选仅限管理员", required_roles=["admin"], actual_role=role)
            now = datetime.now()
            flagged = []
            for r in conn.execute("SELECT wo.*, a.workshop AS w FROM work_orders wo JOIN assets a"
                                  " ON a.asset_id = wo.asset_id").fetchall():
                age = (now - parse_ts(r["reported_at"])).total_seconds() / 3600.0
                if r["status"] != "closed" and age > SLA_HOURS[r["priority"]]:
                    flagged.append(r["work_order_id"])
            if not flagged:
                return ok([], {"page": 1, "page_size": int(request.args.get("page_size", 20) or 20),
                               "total": 0, "filtered_role_scope": scope, "filters": {"sla_risk": True}})
            clauses.append("wo.work_order_id IN (%s)" % ",".join("?" * len(flagged)))
            params.extend(flagged)

        page = request.args.get("page", "1")
        page_size = request.args.get("page_size", "20")
        try:
            page = max(int(page), 1)
            page_size = min(max(int(page_size), 1), 100)
        except (TypeError, ValueError):
            raise err_validation("page", "must_be_integer")

        where = (" WHERE " + " AND ".join(clauses)) if clauses else ""
        base = ("FROM work_orders wo JOIN assets a ON a.asset_id = wo.asset_id" + where)
        total = conn.execute("SELECT COUNT(*) " + base, params).fetchone()[0]
        rows = conn.execute(
            "SELECT wo.* " + base + " ORDER BY wo.work_order_id LIMIT ? OFFSET ?",
            params + [page_size, (page - 1) * page_size]).fetchall()
        filters = {k: request.args.get(k) for k in ("status", "priority", "workshop", "asset_id", "assigned_to",
                                                    "sla_risk") if request.args.get(k)}
        meta = {"page": page, "page_size": page_size, "total": total, "filtered_role_scope": scope,
                "filters": filters}
        return ok([work_order_dict(conn, r) for r in rows], meta)

