    @app.post("/api/work_orders/<wo_id>/part_issues")
    @login_required
    @idempotent("issue_part", replay_authz=_part_issue_replay_guard)
    def api_part_issues_create(wo_id):
        conn = get_conn()
        body = g.idempotency_body
        reject_identity_fields(conn, body)
        reject_unknown(body, {"part_id", "quantity"})
        part_id = pick_str(body, "part_id", required=True, max_len=16)
        quantity = pick_int(body, "quantity", required=True, minimum=1)
        try:
            conn.execute("BEGIN IMMEDIATE")
            wo = fetch_work_order(conn, wo_id)
            if not wo:
                raise err_not_found("work_order", wo_id)
            actor_id = g.session["user"]["user_id"]
            actor_role = g.session["user"]["role"]
            visible_work_order(conn, wo, actor_role, actor_id, action="issue")
            if actor_role not in ("engineer", "admin"):
                raise err_forbidden("角色 %s 无权领用备件" % actor_role,
                                    required_roles=["engineer", "admin"], actual_role=actor_role)
            if wo["status"] not in ("assigned", "in_progress"):
                raise err_transition(wo_id, wo["status"], "issue")
            part = fetch_part(conn, part_id)
            if not part:
                raise err_not_found("part", part_id)
            if part["on_hand"] < quantity:
                raise err_stock(part_id, quantity, part["on_hand"])
            ts = now_str()
            cur = conn.execute(
                "UPDATE parts SET on_hand = on_hand - ?, updated_at = ? WHERE part_id = ? AND on_hand >= ?",
                (quantity, ts, part_id, quantity))
            if cur.rowcount == 0:
                raise err_stock(part_id, quantity, part["on_hand"])
            cur = conn.execute(
                "INSERT INTO part_issues (work_order_id, part_id, quantity, issued_to, issued_at,"
                " unit_cost_cny, source) VALUES (?,?,?,?,?,?,?)",
                (wo_id, part_id, quantity, actor_id, ts, part["unit_cost_cny"], dbmod.MARKER_EXTENSION))
            issue_id = cur.lastrowid
            conn.execute("UPDATE work_orders SET required_part = COALESCE(required_part, ?) WHERE work_order_id=?",
                         (part_id, wo_id))
            write_audit(conn, actor_id, "part.issue", wo_id, wo["status"], wo["status"], g.idempotency_key,
                        detail=json.dumps({"part_id": part_id, "quantity": quantity,
                                           "issue_id": issue_id}, ensure_ascii=False))
            conn.execute("COMMIT")
        except Exception:
            if conn.in_transaction:
                conn.execute("ROLLBACK")
            raise
        fresh_part = fetch_part(conn, part_id)
        data = {"issue_id": issue_id, "work_order_id": wo_id, "part_id": part_id, "quantity": quantity,
                "issued_to": actor_id, "issued_at": ts, "unit_cost_cny": part["unit_cost_cny"],
                "part": {"part_id": fresh_part["part_id"], "name": fresh_part["name"],
                         "on_hand": fresh_part["on_hand"], "reorder_point": fresh_part["reorder_point"],
                         "shortage": bool(fresh_part["on_hand"] < fresh_part["reorder_point"])},
                "work_order": {"work_order_id": wo_id, "status": wo["status"]}}
        return 201, {"data": data, "meta": {"source": dbmod.MARKER_EXTENSION}}

