def _sla_rows(conn, work_order_filter=None):
    now = datetime.now()
    rows = conn.execute(
        "SELECT wo.*, a.workshop AS workshop FROM work_orders wo JOIN assets a ON a.asset_id = wo.asset_id"
        " ORDER BY wo.work_order_id").fetchall()
    out = []
    for r in rows:
        if r["status"] == "closed":
            continue
        age = (now - parse_ts(r["reported_at"])).total_seconds() / 3600.0
        sla = SLA_HOURS[r["priority"]]
        if age > sla:
            out.append({"work_order_id": r["work_order_id"], "priority": r["priority"], "status": r["status"],
                        "assigned_to": r["assigned_to"], "reported_at": iso(r["reported_at"]),
                        "age_hours": round(age, 2), "sla_hours": sla, "overdue_hours": round(age - sla, 2),
                        "workshop": r["workshop"]})
    return out


