# ------------------------------------------------------------------ 应用工厂
def create_app(db_path=None):
    resolved = dbmod.resolve_db_path(db_path)
    app = Flask(__name__, static_folder=None)
    app.config["APP_DB_PATH"] = resolved
    app.json.ensure_ascii = False

    @app.before_request
    def _bind_db():
        g.db_path = resolved
        g.seed_checked = False
        g.conn_failed = False
        g.idempotency_key = None
        g.idempotency_body = None

    @app.teardown_request
    def _release_db(exc=None):
        return close_conn(exc)

    @app.get("/api/health")
    def api_health():
        conn = get_conn()
        ensure_ready()
        return ok({"status": "ok", "service": "maintenance-work-order-backend",
                   "db_path": resolved, "started_at": APP_STARTED_AT, "time": now_str(),
                   "data_source": dbmod.MARKER_FIXTURE,
                   "counts": dbmod.counts(conn)})

    register_session_routes(app)
    register_asset_routes(app)
    register_part_routes(app)
    register_work_order_routes(app)
    register_stats_routes(app)

    # ---------------- 前端静态托管（index.html 位于 app/frontend/） ----------------
    @app.get("/")
    def _index():
        if os.path.isfile(os.path.join(FRONTEND_DIR, "index.html")):
            return send_from_directory(FRONTEND_DIR, "index.html")
        return redirect("/api/health")

    @app.get("/<path:filename>")
    def _static(filename):
        full = os.path.join(FRONTEND_DIR, filename)
        if os.path.isfile(full):
            return send_from_directory(FRONTEND_DIR, filename)
        raise err_not_found("static", filename)

    # ---------------- 统一错误响应 ----------------
    @app.errorhandler(ApiError)
    def _handle_api_error(exc):
        conn = g.get("conn")
        if conn is not None and exc.code == "INTERNAL_ERROR":
            write_audit(conn, None, "internal_error", detail=exc.message)
        return jsonify(exc.envelope()), exc.status

    @app.errorhandler(404)
    def _handle_404(exc):
        return jsonify(ApiError("NOT_FOUND", "路径不存在", 404,
                                {"path": request.path}).envelope()), 404

    @app.errorhandler(405)
    def _handle_405(exc):
        return jsonify(ApiError("METHOD_NOT_ALLOWED", "方法不被允许", 405,
                                {"path": request.path, "method": request.method}).envelope()), 405

    @app.errorhandler(413)
    def _handle_413(exc):
        return jsonify(ApiError("VALIDATION_ERROR", "请求体过大", 400,
                                {"field": "body"}).envelope()), 400

    @app.errorhandler(Exception)
    def _handle_unexpected(exc):
        if isinstance(exc, ApiError):
            return jsonify(exc.envelope()), exc.status
        app.logger.exception("未预期异常：%s", exc)
        conn = g.get("conn")
        if conn is not None:
            try:
                write_audit(conn, None, "internal_error", detail=type(exc).__name__)
            except sqlite3.Error:
                pass
        return jsonify(ApiError("INTERNAL_ERROR", "服务端内部错误", 500, {}).envelope()), 500

    return app


def build_parser():
    parser = argparse.ArgumentParser(description="设备维修工单协同平台后端（synthetic_fixture，本地演示）")
    parser.add_argument("--db", default=None, help="SQLite 运行库路径（环境变量 APP_DB_PATH 优先）")
    parser.add_argument("--port", type=int, default=None, help="监听端口（环境变量 APP_PORT/PORT 优先）")
    parser.add_argument("--host", default="127.0.0.1", help="监听地址，默认 127.0.0.1")
    parser.add_argument("--no-seed", action="store_true", help="跳过启动时的幂等初始化")
    parser.add_argument("--check", action="store_true", help="仅执行 schema + 幂等初始化并打印计数")
    return parser


def resolve_port(port_arg=None):
    for name in ("APP_PORT", "PORT"):
        value = os.environ.get(name)
        if value:
            try:
                return int(value)
            except ValueError:
                raise SystemExit("环境变量 %s 必须是整数，当前为 %r" % (name, value))
    return int(port_arg) if port_arg else 8000


def main(argv=None):
    args = build_parser().parse_args(argv)
    db_path = dbmod.resolve_db_path(args.db)
    directory = os.path.dirname(os.path.abspath(db_path))
    if directory:
        os.makedirs(directory, exist_ok=True)
    conn = dbmod.connect(db_path)
    try:
        if not args.no_seed:
            stats = dbmod.seed(conn, verbose=True)
            print("[startup] 幂等初始化完成：", json.dumps(stats, ensure_ascii=False))
        else:
            # --no-seed 只跳过种子写入；schema 建成仍是服务先决条件，幂等执行且不清空既有数据。
            dbmod.init_schema(conn)
        counts = dbmod.counts(conn)
    finally:
        conn.close()
    if args.check:
        print("[check] 计数：", json.dumps(counts, ensure_ascii=False))
        return 0

    port = resolve_port(args.port)
    app = create_app(db_path)
    print("[startup] db_path=%s" % db_path)
    print("[startup] health=http://%s:%d/api/health" % (args.host, port))
    print("[startup] frontend=http://%s:%d/" % (args.host, port))
    print("[startup] listening_port=%d" % port)
    app.run(host=args.host, port=port, debug=False, threaded=True)
    return 0


if __name__ == "__main__":
    sys.exit(main())

