_BASELINE = {}
_FAILURES = []


def now_iso() -> str:
    return datetime.now().isoformat(timespec="seconds")


def sha256_file(path) -> str | None:
    p = Path(path)
    if not p.is_file():
        return None
    h = hashlib.sha256()
    with open(p, "rb") as fh:
        for chunk in iter(lambda: fh.read(1 << 16), b""):
            h.update(chunk)
    return h.hexdigest()


def record(key: str, value) -> None:
    EVIDENCE[key] = value


def append_list(key: str, item) -> None:
    EVIDENCE.setdefault(key, []).append(item)


def add_note(text: str) -> None:
    EVIDENCE["notes"].append({"at": now_iso(), "note": text})


def baseline() -> dict:
    return dict(_BASELINE)


def session_start() -> None:
    """在任何测试执行前捕获基线（演示库、后端源码、契约文档）。"""
    _BASELINE.update({
        "started_at": now_iso(),
        "run_id": "run-%s" % uuid.uuid4().hex[:12],
        "demo_db_sha256_before": sha256_file(DEMO_DB),
        "app_py_sha256": sha256_file(BACKEND_DIR / "app.py"),
        "interface_md_sha256": sha256_file(INTERFACE_MD),
        "python": sys.version.split()[0],
        "ambient_APP_DB_PATH": os.environ.get("APP_DB_PATH"),
    })
    record("run_id", _BASELINE["run_id"])
    record("isolation", {
        "demo_db_path": str(DEMO_DB),
        "demo_db_sha256_before": _BASELINE["demo_db_sha256_before"],
        "demo_db_sha256_expected": DEMO_SHA_EXPECTED,
        "demo_db_present": Path(DEMO_DB).is_file(),
        "ambient_APP_DB_PATH": _BASELINE["ambient_APP_DB_PATH"],
        "strategy": "每个测试使用 tmp_path 下的独立 SQLite 文件；端到端测试使用独立临时库 + 随机空闲端口启动真实服务；演示库只读校验",
    })


def session_end() -> dict:
    after = sha256_file(DEMO_DB)
    iso = EVIDENCE["isolation"]
    iso["demo_db_sha256_after"] = after
    iso["demo_db_unchanged"] = (after == iso.get("demo_db_sha256_before"))
    iso["demo_db_matches_frozen_hash"] = (after == DEMO_SHA_EXPECTED)
    return after


# ---------------------------------------------------------------- 网络工具
def free_port() -> int:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.bind(("127.0.0.1", 0))
        return int(s.getsockname()[1])


def wait_http_ready(url: str, timeout: float = 30.0) -> bool:
    import urllib.error
    import urllib.request
    deadline = time.time() + timeout
    while time.time() < deadline:
        try:
            with urllib.request.urlopen(url, timeout=2) as resp:
                if resp.status == 200:
                    return True
        except urllib.error.URLError:
            time.sleep(0.25)
        except Exception:
            time.sleep(0.25)
    return False


class LiveServer:
    """以独立临时库启动交付版后端（app.py），等待健康检查通过。"""

    def __init__(self, db_path: str, log_path: Path, port: int | None = None):
        self.db_path = str(db_path)
        self.port = int(port or free_port())
        self.base_url = "http://127.0.0.1:%d" % self.port
        self.log_path = Path(log_path)
        self.proc: subprocess.Popen | None = None
        self.cmd: list[str] = []
        self.spawn()

    def spawn(self) -> None:
        self.log_path.parent.mkdir(parents=True, exist_ok=True)
        self._log_fh = open(self.log_path, "ab")
        self.cmd = [sys.executable, str(BACKEND_DIR / "app.py"),
                    "--db", self.db_path, "--port", str(self.port)]
        env = dict(os.environ)
        env["APP_DB_PATH"] = self.db_path
        env["APP_PORT"] = str(self.port)
        env["PYTHONUNBUFFERED"] = "1"
        self.proc = subprocess.Popen(self.cmd, cwd=str(BACKEND_DIR), env=env,
                                     stdout=self._log_fh, stderr=subprocess.STDOUT)
        if not wait_http_ready(self.base_url + "/api/health", timeout=30):
            self.stop()
            raise RuntimeError("真实服务启动失败，健康检查未就绪：%s（日志 %s）"
                               % (self.base_url, self.log_path))

    def stop(self) -> None:
        if self.proc is not None:
            try:
                self.proc.terminate()
                self.proc.wait(timeout=10)
            except Exception:
                try:
                    self.proc.kill()
                except Exception:
                    pass
            self.proc = None
        try:
            self._log_fh.close()
        except Exception:
            pass

    def restart(self, port: int | None = None) -> None:
        self.stop()
        if port:
            self.port = int(port)
            self.base_url = "http://127.0.0.1:%d" % self.port
        self.spawn()

    def log_tail(self, limit: int = 1200) -> str:
        if not self.log_path.is_file():
            return ""
        text = self.log_path.read_text(encoding="utf-8", errors="replace")
        return text[-limit:]

    def __enter__(self) -> "LiveServer":
        return self

    def __exit__(self, *exc) -> None:
        self.stop()


class SessionApi:
    """最小会话客户端（契约 §4.1：X-Session-Token）。

    与 conftest.Api 行为一致，但用标准库直接包装 flask test_client，
    供不依赖 pytest 夹具的辅助场景使用（避免 conftest 循环导入）。
    """

    def __init__(self, flask_app, username=None, password=PASSWORD):
        self.flask_app = flask_app
        self.client = flask_app.test_client()
        self.token = None
        self.user = None
        if username:
            self.login(username, password)

    def login(self, username, password=PASSWORD):
        resp = self.client.post("/api/login", json={"username": username, "password": password})
        if resp.status_code == 200:
            data = resp.get_json()["data"]
            self.token = data["session_token"]
            self.user = data["user"]
        return resp

    def _headers(self, key=None):
        headers = {}
        if self.token:
            headers["X-Session-Token"] = self.token
        if key is not None:
            headers["X-Idempotency-Key"] = key
        return headers

    def get(self, path, key=None):
        return self.client.get(path, headers=self._headers(key))

    def post(self, path, body=None, key=None):
        return self.client.post(path, json={} if body is None else body, headers=self._headers(key))

    def put(self, path, body=None, key=None):
        return self.client.put(path, json=body or {}, headers=self._headers(key))

    def delete(self, path, key=None):
        return self.client.delete(path, headers=self._headers(key))


