# ---------------------------------------------------------------- 报告写出
def _file_sha256(path) -> str | None:
    try:
        with open(path, "rb") as fh:
            return hashlib.sha256(fh.read()).hexdigest()
    except OSError:
        return None


def _test_file_hashes() -> dict:
    """测试侧文件哈希（证明本轮报告由当前测试文件执行得出）。"""
    out = {}
    for p in sorted(TESTS_DIR.glob("*.py")):
        out[p.name] = {"path": str(p), "sha256": _file_sha256(p)}
    return out


def _collapse(records: dict) -> list[dict]:
    out = []
    for nodeid, entries in records.items():
        chosen = None
        for e in entries:
            if e["when"] == "call":
                chosen = e
                break
        if chosen is None:
            chosen = entries[-1]
        outcome = chosen["outcome"]
        reason = chosen.get("reason")
        if reason:
            # pytest 对 xfail 用例在 call 阶段报 skipped(wasxfail) / passed(wasxfail)。
            # 如实折算为 xfailed / xpassed，避免把「与契约不一致的实测行为」计入 skipped 或 passed。
            if outcome == "skipped":
                outcome = "xfailed"
            elif outcome == "passed":
                outcome = "xpassed"
        item = {"nodeid": nodeid, "outcome": outcome}
        if reason:
            item["reason"] = reason
        if chosen.get("detail"):
            item["detail"] = chosen["detail"]
        out.append(item)
    out.sort(key=lambda x: x["nodeid"])
    return out


