class Api:
    """按 interface.md §4.1 使用 X-Session-Token 的 Flask test_client 封装。"""

    def __init__(self, flask_app, username=None, password=sup.PASSWORD):
        self.flask_app = flask_app
        self.client = flask_app.test_client()
        self.token = None
        self.user = None
        if username:
            self.login(username, password)

    def login(self, username, password=sup.PASSWORD):
        resp = self.client.post("/api/login", json={"username": username, "password": password})
        if resp.status_code == 200:
            data = resp.get_json()["data"]
            self.token = data["session_token"]
            self.user = data["user"]
        return resp

    def _headers(self, key=None, extra=None):
        headers = {}
        if self.token:
            headers["X-Session-Token"] = self.token
        if key is not None:
            headers["X-Idempotency-Key"] = key
        if extra:
            headers.update(extra)
        return headers

    def get(self, path, key=None, headers=None, **kw):
        return self.client.get(path, headers=self._headers(key, headers), **kw)

    def post(self, path, body=None, key=None, headers=None, raw=None):
        kwargs = {}
        if raw is not None:
            kwargs["data"] = raw
            headers = dict(headers or {})
            headers.setdefault("Content-Type", "application/json")
        else:
            kwargs["json"] = {} if body is None else body
        return self.client.post(path, headers=self._headers(key, headers), **kwargs)

    def put(self, path, body=None, key=None, headers=None):
        return self.client.put(path, json=body or {}, headers=self._headers(key, headers))

    def delete(self, path, key=None, headers=None):
        return self.client.delete(path, headers=self._headers(key, headers))


def code_of(resp):
    """读取统一错误信封的 error.code（非 JSON 时返回 None）。"""
    try:
        payload = resp.get_json()
    except Exception:
        return None
    if isinstance(payload, dict) and isinstance(payload.get("error"), dict):
        return payload["error"].get("code")
    return None


def details_of(resp):
    try:
        return resp.get_json()["error"].get("details") or {}
    except Exception:
        return {}


def data_of(resp):
    payload = resp.get_json()
    assert payload is not None, "响应不是 JSON：%s" % resp.get_data(as_text=True)[:200]
    assert payload.get("ok") is True, "ok 不为 True：%s" % str(payload)[:200]
    return payload["data"]


def meta_of(resp):
    payload = resp.get_json()
    assert payload is not None, "响应不是 JSON"
    return payload.get("meta") or {}


def assert_error(resp, expected_code, expected_status=None):
    """按 §4.3 断言 error.code（并核对 http_status）。"""
    payload = resp.get_json()
    assert isinstance(payload, dict) and payload.get("ok") is False, \
        "期望统一错误信封，实际：%s" % resp.get_data(as_text=True)[:200]
    err = payload["error"]
    assert err["code"] == expected_code, "期望 %s，实际 %s" % (expected_code, err)
    if expected_status is not None:
        assert resp.status_code == expected_status, (resp.status_code, expected_status)
        assert err["http_status"] == expected_status, err
    return err


