    return "%s-%s" % (prefix, uuid.uuid4().hex[:12])


def on_hand(db_path, part_id):
    """直接读临时库核对库存（独立于 API 返回值）。"""
    conn = backend_db.connect(str(db_path))
    try:
        row = conn.execute("SELECT on_hand FROM parts WHERE part_id=?", (part_id,)).fetchone()
        return None if row is None else row["on_hand"]
    finally:
        conn.close()


def sqlite_scalar(db_path, sql, params=()):
    conn = backend_db.connect(str(db_path))
    try:
        row = conn.execute(sql, params).fetchone()
        return None if row is None else row[0]
    finally:
        conn.close()


