        print("[N-TESTS] 计数：%s" % totals)

/* 设备维修工单协同平台 — 前端逻辑（原生 JavaScript，无外部依赖）
 * 契约：deliverables/docs/interface.md（IC-MAINT-1.0，frozen）
 * 规则：
 *  - 只调用 §6 端点总表中的路由，不构造别名路由。
 *  - 登录只发送 username/password；绝不发送 role/user_id/actor_id/reporter_id（服务端会 400）。
 *  - 后续操作身份来自服务端会话（HttpOnly Cookie session_token，凭证同源自动携带）。
 *  - 写操作必须携带 X-Idempotency-Key；重试同一表单复用同一键。
 *  - 前端按钮可见性仅为体验层，不构成权限控制。
 */
'use strict';

const EP = {
  health: '/api/health',
  login: '/api/login',
  logout: '/api/logout',
  session: '/api/session',
  engineers: '/api/users/engineers',
  workshops: '/api/workshops',
  assetOptions: '/api/assets/options',
  parts: '/api/parts',
  workOrders: '/api/work_orders',
  statsOverview: '/api/stats/overview',
  statsSlaRisk: '/api/stats/sla_risk',
  statsPartShortage: '/api/stats/part_shortage',
  statsByWorkshop: '/api/stats/by_workshop'
};

const SCOPE = {
  createWorkOrder: 'create_work_order',
  assign: 'assign',
  start: 'start',
  complete: 'complete',
  close: 'close',
  issuePart: 'issue_part'
};

const STATE = {
  user: null,          // 来自服务端会话的 user 对象（role 以其为准）
  retryKeys: {}        // 表单重试键：create / issue
};

// ------------------------------------------------------------------ 基础工具
function $(id) { return document.getElementById(id); }

function esc(v) {
  return String(v === null || v === undefined ? '' : v)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function newKey(prefix) {
  const rand = (window.crypto && window.crypto.randomUUID)
    ? window.crypto.randomUUID()
    : (Date.now().toString(36) + Math.random().toString(36).slice(2));
  return (prefix || 'web') + '-' + rand;
}

function show(id, text, kind) {
  const el = $(id);
  if (!el) return;
  el.textContent = text;
  el.className = 'result' + (kind ? ' ' + kind : '');
}

function pill(value, kind) {
  return '<span class="pill ' + esc(kind || value) + '">' + esc(value) + '</span>';
}

async function api(method, path, options) {
  const opt = options || {};
  const headers = {};
  if (opt.body !== undefined && opt.body !== null) headers['Content-Type'] = 'application/json';
  if (opt.idempotencyKey) headers['X-Idempotency-Key'] = opt.idempotencyKey;
  let res, text;
  try {
    res = await fetch(path, {
      method: method,
      headers: headers,
      credentials: 'same-origin',      // 会话凭证来自同源 Cookie
      body: (opt.body === undefined || opt.body === null) ? undefined : JSON.stringify(opt.body)
    });
    text = await res.text();
  } catch (netErr) {
    return { ok: false, status: 0, json: null, raw: String(netErr),
             error: { code: 'NETWORK_ERROR', message: '无法访问服务端：' + netErr, http_status: 0, details: {} } };
  }
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch (e) { json = null; }
  if (json && json.ok === false && json.error) {
    return { ok: false, status: res.status, json: json, raw: text, error: json.error };
  }
  if (!json || json.ok !== true) {
    return { ok: false, status: res.status, json: json, raw: text,
             error: { code: 'UNEXPECTED_RESPONSE', message: '响应不符合统一封装', http_status: res.status, details: {} } };
  }
  return { ok: true, status: res.status, json: json, raw: text, data: json.data, meta: json.meta || {} };
}

function brief(label, r) {
  if (r.ok) {
    return label + ' → HTTP ' + r.status + ' OK\n' + JSON.stringify({ data: r.data, meta: r.meta }, null, 2);
  }
  const e = r.error || {};
  return label + ' → HTTP ' + (r.status || 0) + ' 失败\n' + JSON.stringify(
    { ok: false, error: { code: e.code, message: e.message, http_status: e.http_status, details: e.details } }, null, 2);
}

function isForbidden(r) { return !r.ok && r.error && r.error.code === 'FORBIDDEN'; }

// ------------------------------------------------------------------ 登录 / 会话
async function doLogin(event) {
  if (event) event.preventDefault();
  const username = $('login-username').value;
  const password = $('login-password').value;
  // 只发送 username/password：身份来自服务端会话，不提交任何角色声明字段
  const r = await api('POST', EP.login, { body: { username: username, password: password } });
  show('login-result', brief('POST /api/login  (' + username + ')', r), r.ok ? 'ok' : 'err');
  if (!r.ok) return;
  STATE.user = r.data.user;
  await afterLogin();
}

async function refreshSession(quiet) {
  const r = await api('GET', EP.session);
  if (!quiet) show('detail-result', brief('GET /api/session', r), r.ok ? 'ok' : 'err');
  if (!r.ok) { renderLoggedOut(); return null; }
  STATE.user = r.data.user;
  await afterLogin();
  return STATE.user;
}

async function afterLogin() {
  const u = STATE.user;
  $('view-login').classList.add('hide-when-logged');
  $('login-result').className = 'result ok';
  $('login-result').textContent = '已建立服务端会话：' + JSON.stringify(u, null, 2) +
    '\n（角色以本会话为准；刷新会话可验证身份确实来自服务端）';
  $('app-shell').hidden = false;
  $('session-box').hidden = false;
  $('session-info').textContent = u.name + ' · ' + u.user_id + ' · role=' + u.role +
    (u.workshop ? ' · ' + u.workshop : '');
  applyRoleVisibility();
  await Promise.all([loadWorkshops(), loadAssetOptions(), loadParts()]);
  switchView('orders');
  await loadOrders();
}

function applyRoleVisibility() {
  const role = STATE.user ? STATE.user.role : null;
  // 仅为体验层的按钮可见性；服务端独立校验并会拒绝越权调用
  $('tabs').querySelector('[data-view="assign"]').hidden = (role !== 'admin');
  $('tabs').querySelector('[data-view="stats"]').hidden = (role !== 'admin');
  $('tabs').querySelector('[data-view="create"]').hidden = (role === 'engineer');
}

function renderLoggedOut() {
  STATE.user = null;
  $('view-login').classList.remove('hide-when-logged');
  $('app-shell').hidden = true;
  $('session-box').hidden = true;
}

async function doLogout() {
  const r = await api('POST', EP.logout);
  show('login-result', brief('POST /api/logout', r), r.ok ? 'ok' : 'err');
  if (r.ok) renderLoggedOut();
}

