async function loadOrders(event) {
  if (event) event.preventDefault();
  const params = new URLSearchParams();
  const st = $('flt-status').value;
  const pr = $('flt-priority').value;
  const ws = $('flt-workshop').value;
  if (st) params.set('status', st);
  if (pr) params.set('priority', pr);
  if (ws) params.set('workshop', ws);
  params.set('page', '1');
  params.set('page_size', $('flt-page-size').value);
  const r = await api('GET', EP.workOrders + '?' + params.toString());
  const body = $('orders-body');
  body.innerHTML = '';
  if (!r.ok) {
    body.innerHTML = '<tr><td colspan="10" class="empty">加载失败</td></tr>';
    show('orders-result', brief('GET /api/work_orders?' + params.toString(), r), 'err');
    return;
  }
  const rows = r.data || [];
  if (!rows.length) body.innerHTML = '<tr><td colspan="10" class="empty">无匹配工单</td></tr>';
  rows.forEach(function (wo) {
    const a = wo.asset || {};
    const tr = document.createElement('tr');
    tr.innerHTML =
      '<td>' + esc(wo.work_order_id) + '</td>' +
      '<td>' + esc(a.asset_name || wo.asset_id) + '<br><span class="hint">' + esc(wo.asset_id) + '</span></td>' +
      '<td>' + esc(a.workshop || '') + '</td>' +
      '<td>' + pill(wo.priority, wo.priority) + '</td>' +
      '<td>' + pill(wo.status, wo.status) + '</td>' +
      '<td>' + esc(wo.reporter_id) + '</td>' +
      '<td>' + esc(wo.assigned_to || '未分配') + '</td>' +
      '<td>' + esc(wo.required_part || '—') + '</td>' +
      '<td>' + esc(wo.reported_at) + '</td>' +
      '<td><button class="btn" type="button" data-open="' + esc(wo.work_order_id) + '">查看详情</button></td>';
    body.appendChild(tr);
  });
  Array.prototype.forEach.call(body.querySelectorAll('[data-open]'), function (btn) {
    btn.addEventListener('click', function () {
      $('detail-id').value = btn.getAttribute('data-open');
      switchView('detail');
      loadDetail();
    });
  });
  const meta = r.meta || {};
  $('orders-meta').textContent = '共 ' + (meta.total === undefined ? rows.length : meta.total) +
    ' 条 · page=' + (meta.page || 1) + ' · page_size=' + (meta.page_size || 20) +
    ' · filtered_role_scope=' + (meta.filtered_role_scope || '-') +
    ' · filters=' + JSON.stringify(meta.filters || {});
  show('orders-result', brief('GET /api/work_orders?' + params.toString(), r), 'ok');
}

// ------------------------------------------------------------------ 创建报修
async function createOrder(event) {
  if (event) event.preventDefault();
  const assetId = $('create-asset').value;
  const desc = $('create-desc').value.trim();
  if (!assetId) { show('create-result', '请先选择设备（asset_id 必填）', 'err'); return; }
  if (desc.length < 5 || desc.length > 500) {
    show('create-result', 'fault_desc 需为 5–500 字（当前 ' + desc.length + ' 字）', 'err');
    return;
  }
  const payload = { asset_id: assetId, fault_desc: desc, priority: $('create-priority').value };
  const part = $('create-required-part').value;
  if (part) payload.required_part = part;               // 可空字段：不选则不发送
  const key = STATE.retryKeys.create || newKey('create');
  STATE.retryKeys.create = key;
  const r = await api('POST', EP.workOrders, { body: payload, idempotencyKey: key });
  show('create-result', brief('POST /api/work_orders  (X-Idempotency-Key: ' + key + ')', r), r.ok ? 'ok' : 'err');
  if (r.ok) {
    STATE.retryKeys.create = null;
    $('create-retry').hidden = true;
    $('create-desc').value = '';
    await loadOrders();
  } else {
    $('create-retry').hidden = false;   // 4xx 不占用幂等键，可用同键修正后重试
  }
}

async function retryCreate() {
  const key = STATE.retryKeys.create || newKey('create');
  STATE.retryKeys.create = key;
  const payload = {
    asset_id: $('create-asset').value,
    fault_desc: $('create-desc').value.trim(),
    priority: $('create-priority').value
  };
  const part = $('create-required-part').value;
  if (part) payload.required_part = part;
  const r = await api('POST', EP.workOrders, { body: payload, idempotencyKey: key });
  show('create-result', brief('POST /api/work_orders 重试 (同一键 ' + key + ')', r), r.ok ? 'ok' : 'err');
  if (r.ok) { STATE.retryKeys.create = null; $('create-retry').hidden = true; await loadOrders(); }
}

