    });
  } else {
    wsBody.innerHTML = '<tr><td colspan="7" class="empty">' +
      (ws.ok ? '无数据' : '不可用：' + esc((ws.error || {}).code)) + '</td></tr>';
  }

  show('stats-result',
    [brief('GET /api/stats/overview', ov), brief('GET /api/stats/sla_risk', sla),
     brief('GET /api/stats/part_shortage', sh), brief('GET /api/stats/by_workshop', ws)].join('\n\n'),
    ov.ok ? 'ok' : 'err');
}

// ------------------------------------------------------------------ 工单详情
async function loadDetail(event) {
  if (event) event.preventDefault();
  const id = ($('detail-id').value || '').trim();
  if (!id) { show('detail-result', '请输入或从列表选择 work_order_id', 'err'); return; }
  const r = await api('GET', EP.workOrders + '/' + encodeURIComponent(id));
  if (!r.ok) {
    $('detail-body').hidden = true;
    show('detail-result', brief('GET /api/work_orders/' + id, r), 'err');
    return;
  }
  const wo = r.data;
  $('detail-body').hidden = false;
  const kv = [
    ['work_order_id', wo.work_order_id], ['status', wo.status], ['priority', wo.priority],
    ['asset_id', wo.asset_id],
    ['设备', (wo.asset ? wo.asset.asset_name + ' · ' + wo.asset.workshop : '')],
    ['fault_desc', wo.fault_desc], ['reporter_id', wo.reporter_id],
    ['assigned_to', wo.assigned_to || '未分配'], ['required_part', wo.required_part || '—'],
    ['reported_at', wo.reported_at], ['assigned_at', wo.assigned_at || '—'],
    ['started_at', wo.started_at || '—'], ['completed_at', wo.completed_at || '—'],
    ['closed_at', wo.closed_at || '—'], ['resolution_note', wo.resolution_note || '—']
  ];
  $('detail-fields').innerHTML = kv.map(function (p) {
    return '<dt>' + esc(p[0]) + '</dt><dd>' + esc(p[1]) + '</dd>';
  }).join('');
  const tb = $('detail-issues-body');
  tb.innerHTML = '';
  const issues = wo.part_issues || [];
  if (!issues.length) tb.innerHTML = '<tr><td colspan="6" class="empty">无领用记录</td></tr>';
  issues.forEach(function (it) {
    tb.insertAdjacentHTML('beforeend', '<tr><td>' + esc(it.issue_id) + '</td><td>' + esc(it.part_id) +
      '</td><td>' + esc(it.quantity) + '</td><td>' + esc(it.issued_to) + '</td><td>' + esc(it.issued_at) +
      '</td><td>' + esc(it.unit_cost_cny) + '</td></tr>');
  });
  // 分派按钮仅体验层提示；服务端会独立校验 admin 角色
  $('btn-assign').textContent = '分派 assign（当前状态 ' + wo.status + '）';
  show('detail-result', brief('GET /api/work_orders/' + id, r), 'ok');
}

async function transition(operation, body, keyPrefix) {
  const id = ($('detail-id').value || '').trim();
  if (!id) { show('detail-result', '请先加载工单', 'err'); return; }
  const key = newKey(keyPrefix || operation);
  const r = await api('POST', EP.workOrders + '/' + encodeURIComponent(id) + '/' + operation,
    { body: body, idempotencyKey: key });
  show('detail-result',
    brief('POST /api/work_orders/' + id + '/' + operation + '  (key=' + key + ')', r), r.ok ? 'ok' : 'err');
  if (r.ok) { await loadDetail(); await loadOrders(); }
}

async function issuePart(event) {
  if (event) event.preventDefault();
  const id = ($('detail-id').value || '').trim();
  if (!id) { show('detail-result', '请先加载工单', 'err'); return; }
  const partId = $('issue-part').value;
  const qty = parseInt($('issue-qty').value, 10);
  if (!partId) { show('detail-result', '请选择备件 part_id', 'err'); return; }
  if (!(qty >= 1)) { show('detail-result', 'quantity 必须为 >= 1 的整数', 'err'); return; }
  const key = STATE.retryKeys.issue || newKey('issue');
  STATE.retryKeys.issue = key;
  const r = await api('POST', EP.workOrders + '/' + encodeURIComponent(id) + '/part_issues',
    { body: { part_id: partId, quantity: qty }, idempotencyKey: key });
  show('detail-result', brief('POST /api/work_orders/' + id + '/part_issues  (scope=issue_part, key=' + key + ')', r),
    r.ok ? 'ok' : 'err');
  if (r.ok) {
    STATE.retryKeys.issue = null;
    $('issue-retry').hidden = true;
    await Promise.all([loadDetail(), loadParts(), loadOrders()]);
  } else {
    $('issue-retry').hidden = false;
  }
}

async function retryIssue() {
  const id = ($('detail-id').value || '').trim();
  const key = STATE.retryKeys.issue || newKey('issue');
  STATE.retryKeys.issue = key;
  const r = await api('POST', EP.workOrders + '/' + encodeURIComponent(id) + '/part_issues',
    { body: { part_id: $('issue-part').value, quantity: parseInt($('issue-qty').value, 10) },
      idempotencyKey: key });
  show('detail-result', brief('POST /api/work_orders/' + id + '/part_issues 重试 (同一键 ' + key + ')', r),
    r.ok ? 'ok' : 'err');
  if (r.ok) { STATE.retryKeys.issue = null; $('issue-retry').hidden = true; await loadDetail(); }
}

// ------------------------------------------------------------------ 绑定与启动
function bind() {
  $('login-form').addEventListener('submit', doLogin);
  $('logout-btn').addEventListener('click', doLogout);
  $('refresh-session-btn').addEventListener('click', function () { refreshSession(false); });
  $('tabs').addEventListener('click', function (e) {
    const btn = e.target.closest ? e.target.closest('.tab') : null;
    if (!btn) return;
    const v = btn.getAttribute('data-view');
    switchView(v);
    if (v === 'orders') loadOrders();
    if (v === 'assign') loadAssignBoard();
    if (v === 'stats') loadStats();
    if (v === 'detail') loadEngineers('detail-assignee');
  });
  $('orders-filter').addEventListener('submit', loadOrders);
  $('orders-reload').addEventListener('click', function () { loadOrders(); });
  $('orders-reset').addEventListener('click', function () {
    $('flt-status').value = ''; $('flt-priority').value = ''; $('flt-workshop').value = '';
    $('flt-page-size').value = '20';
    loadOrders();
  });
  $('create-form').addEventListener('submit', createOrder);
  $('create-retry').addEventListener('click', retryCreate);
  $('assign-filter').addEventListener('submit', submitAssign);
  $('assign-reload').addEventListener('click', loadAssignBoard);
  $('stats-reload').addEventListener('click', loadStats);
  $('detail-load').addEventListener('submit', loadDetail);
  $('detail-engineers').addEventListener('click', async function () {
    const r = await loadEngineers('detail-assignee');
    show('detail-result', brief('GET /api/users/engineers', r), r.ok ? 'ok' : 'err');
  });
  $('btn-assign').addEventListener('click', function () {
    const to = $('detail-assignee').value;
    if (!to) { show('detail-result', '请先点击「加载工程师列表（admin）」并选择工程师', 'err'); return; }
    transition('assign', { assigned_to: to }, 'assign');
  });
  $('btn-start').addEventListener('click', function () { transition('start', {}, 'start'); });
  $('btn-complete').addEventListener('click', function () {
    const note = $('complete-note').value.trim();
    if (note.length < 1 || note.length > 500) {
      show('detail-result', 'resolution_note 必填且为 1–500 字', 'err'); return;
    }
    transition('complete', { resolution_note: note }, 'complete');
  });
  $('btn-close').addEventListener('click', function () {
    const note = $('close-note').value.trim();
    transition('close', note ? { note: note } : {}, 'close');
  });
  $('issue-form').addEventListener('submit', issuePart);
  $('issue-retry').addEventListener('click', retryIssue);
}

async function boot() {
  bind();
  const h = await api('GET', EP.health);
  if (!h.ok) {
    show('login-result', '服务健康检查失败：' + brief('GET /api/health', h), 'err');
    return;
  }
  show('login-result', brief('GET /api/health', h) + '\n\n请选择演示账号登录（身份来自服务端会话）。', 'ok');
  const s = await api('GET', EP.session);       // 已有会话则自动恢复身份
  if (s.ok) { STATE.user = s.data.user; await afterLogin(); }
  else renderLoggedOut();
}

document.addEventListener('DOMContentLoaded', boot);

:root {
  --bg: #f5f7fa;
  --card: #ffffff;
  --line: #d7dde5;
  --text: #1f2933;
  --muted: #6b7684;
  --primary: #1f6feb;
  --primary-dark: #1857b8;
  --ok: #127c4a;
  --warn: #b45309;
  --err: #b42318;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  padding: 0 0 40px;
  background: var(--bg);
  color: var(--text);
  font: 14px/1.55 "Segoe UI", "Microsoft YaHei", system-ui, -apple-system, sans-serif;
}

.topbar {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: 12px 20px; background: #10243e; color: #fff;
}
.brand strong { font-size: 16px; }
.tag { margin-left: 8px; font-size: 12px; color: #9dc0ea; }
.session-box { display: flex; align-items: center; gap: 8px; }
.session-info { font-size: 12px; color: #d7e6f8; }

.notice {
  margin: 12px 20px; padding: 10px 14px; background: #fffbe6; border: 1px solid #f2d98c;
  border-radius: 6px; font-size: 12.5px; color: #5c4708;
}

.card {
  background: var(--card); margin: 14px 20px; padding: 16px 18px;
  border: 1px solid var(--line); border-radius: 8px;
}
.card h2 { margin: 0 0 12px; font-size: 16px; }
.card h3 { margin: 18px 0 8px; font-size: 14px; }
.view { display: none; }
.view.active { display: block; }
#view-login { display: block; }
#view-login.hide-when-logged { display: none; }

.tabs { display: flex; flex-wrap: wrap; gap: 6px; margin: 14px 20px 0; }
.tab {
  padding: 7px 14px; border: 1px solid var(--line); background: #fff;
  border-radius: 6px 6px 0 0; cursor: pointer; font-size: 13px; color: var(--text);
}
.tab.active { background: var(--primary); border-color: var(--primary); color: #fff; }

.form-row { display: flex; flex-wrap: wrap; gap: 12px; align-items: flex-end; margin: 0 0 12px; }
.form-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 12px; }
.field { display: flex; flex-direction: column; gap: 4px; min-width: 180px; font-size: 12.5px; color: var(--muted); }
.field.wide { grid-column: 1 / -1; }
.field input, .field select, .field textarea {
  padding: 6px 8px; border: 1px solid var(--line); border-radius: 5px;
  font: inherit; color: var(--text); background: #fff; min-width: 0;
}
.actions { display: flex; flex-wrap: wrap; gap: 8px; align-items: flex-end; grid-column: 1 / -1; }

.btn {
  padding: 7px 13px; border: 1px solid var(--line); background: #fff; color: var(--text);
  border-radius: 5px; cursor: pointer; font: inherit; font-size: 13px;
}
.btn:hover { border-color: #a9b6c6; }
.btn-primary { background: var(--primary); border-color: var(--primary); color: #fff; }
.btn-primary:hover { background: var(--primary-dark); border-color: var(--primary-dark); }
.btn-ghost { background: #f0f3f7; }
.btn[disabled] { opacity: .5; cursor: not-allowed; }

.hint, .meta-line { color: var(--muted); font-size: 12.5px; margin: 6px 0; }
.result {
  white-space: pre-wrap; word-break: break-all; background: #f8fafc; border: 1px solid var(--line);
  border-radius: 6px; padding: 9px 11px; font-size: 12px; max-height: 260px; overflow: auto; margin: 10px 0 0;
}
.result.err { background: #fef3f2; border-color: #f5b5ae; color: var(--err); }
.result.ok { background: #f0fdf4; border-color: #a7dfc0; color: var(--ok); }

.table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: 6px; }
.grid { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.grid th, .grid td { padding: 7px 9px; border-bottom: 1px solid var(--line); text-align: left; white-space: nowrap; }
.grid th { background: #eef2f7; font-weight: 600; }
.grid tbody tr:hover { background: #f7fbff; }
.grid .empty { text-align: center; color: var(--muted); }

.pill { padding: 1px 7px; border-radius: 10px; font-size: 11.5px; border: 1px solid transparent; }
.pill.open { background: #eaf2ff; color: #1f4fa8; border-color: #b9d0f5; }
.pill.assigned { background: #fff5e6; color: #94590a; border-color: #f0cf9a; }
.pill.in_progress { background: #e8f6ff; color: #0b6a97; border-color: #a8d8f0; }
.pill.completed { background: #eefbf1; color: var(--ok); border-color: #a7dfc0; }
.pill.closed { background: #eef0f3; color: #4b5563; border-color: #cfd6de; }
.pill.P1 { background: #fdecea; color: var(--err); border-color: #f5b5ae; }
.pill.P2 { background: #fff5e6; color: var(--warn); border-color: #f0cf9a; }
.pill.P3 { background: #eef0f3; color: #4b5563; border-color: #cfd6de; }

.detail-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 18px; }
.kv { display: grid; grid-template-columns: 150px 1fr; gap: 4px 10px; margin: 0; font-size: 12.5px; }
.kv dt { color: var(--muted); }
.kv dd { margin: 0; word-break: break-all; }

.stat-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; }
.stat-card { border: 1px solid var(--line); border-radius: 6px; padding: 10px 12px; background: #f9fbfd; }
.stat-card .k { font-size: 12px; color: var(--muted); }
.stat-card .v { font-size: 20px; font-weight: 600; }
.stat-card.alert .v { color: var(--err); }

.footer { margin: 18px 20px 0; color: var(--muted); font-size: 12px; }
